// ── 런타임 날짜 기준 동적 status 갱신 ──
// 빌드 타임 status는 참고용, 실제 렌더링 시 이 함수로 재계산
export function getDynamicEvents() {
  return EVENTS.map(e => ({
    ...e,
    status: calcStatus(e.start, e.end),
    dday: calcDday(e.start),
  }));
}
